with app.app_context():
    db.create_all()
    print("✅ Tables created successfully!")
    
    # Parse survey data and seed assessment table
    lines = survey_data_raw.strip().split('\n')
    seeded_count = 0
    batches_set = set()
    
    for line in lines:
        parts = line.split('\t')
        if len(parts) >= 22:
            ts = parts[0].strip()
            email = parts[1].strip()
            name = parts[2].strip()
            campus = parts[3].strip()
            batch_name = parts[4].strip()
            mobile = parts[5].strip()
            timings = parts[6].strip()
            sid = parts[7].strip()
            dream = parts[8].strip()
            gender = parts[9].strip()
            age = parts[10].strip()
            qual = parts[11].strip()
            vision = parts[12].strip()
            hobbies = parts[13].strip()
            food = parts[14].strip()
            tv = parts[15].strip()
            talent = parts[16].strip()
            country = parts[17].strip()
            excuse = parts[18].strip()
            superpower = parts[19].strip()
            study_with = parts[20].strip()
            learn_way = parts[21].strip()
            
            batches_set.add(batch_name)
            
            # Check if assessment already exists for this email or student_id
            existing = Assessment.query.filter_by(email_address=email).first()
            if not existing:
                assessment = Assessment(
                    timestamp=ts,
                    email_address=email,
                    name=name,
                    campus=campus,
                    batch=batch_name,
                    register_mobile_number=mobile,
                    timings=timings,
                    student_id=sid,
                    biggest_dream_or_goal=dream,
                    gender=gender,
                    age=age,
                    last_qualification=qual,
                    five_year_vision=vision,
                    favorite_hobbies=hobbies,
                    favorite_food=food,
                    favorite_tv_show=tv,
                    unique_talent=talent,
                    dream_country=country,
                    favorite_excuse=excuse,
                    secret_superpower=superpower,
                    study_session_with=study_with,
                    favorite_way_to_learn=learn_way
                )
                db.session.add(assessment)
                seeded_count += 1
                
    db.session.commit()
    print(f"✅ Successfully seeded {seeded_count} assessment records!")
    
    # Seed Batches
    for b in batches_set:
        if b:
            existing_batch = Batch.query.filter_by(name=b).first()
            if not existing_batch:
                # Bano Qabil 5.0 Fall is ongoing, others active or finished
                is_active = True if '5.0 Fall' in b else False
                new_b = Batch(name=b, is_active=is_active)
                db.session.add(new_b)
    db.session.commit()
    print(f"✅ Batches seeded successfully: {list(batches_set)}")
